SELECT * FROM materials
WHERE user_id = #{userId}
ORDER BY created_at DESC

SELECT m.id, m.title, m.course_tag as courseTag, LEFT(o.ocr_text, 200) as ocrTextSnippet, m.source, m.created_at as createdAt FROM materials m LEFT JOIN ocr_result o ON m.id = o.material_id WHERE m.id IN
#{id}
ORDER BY m.created_at DESC
